// With tracking (default) — slower for read-only data
var trackedProducts = await context.Products
    .Where(p => p.IsActive)
    .ToListAsync();

trackedProducts[0].Price = 99.99m; // this would be persisted by SaveChangesAsync

// Without tracking — faster for read-only data
var readOnlyProducts = await context.Products
    .AsNoTracking()
    .Where(p => p.IsActive)
    .Select(p => new { p.Name, p.Price, Category = p.Category.Name })
    .ToListAsync();

// readOnlyProducts[0].Price = 99.99m; // this change is ignored — no tracking

// N+1 PROBLEM: 1 query for products + N queries for categories
var products = await context.Products.ToListAsync();
foreach (var product in products)
{
    // Each access triggers a separate database query!
    Console.WriteLine($"{product.Name} - {product.Category.Name}");
}
// Total queries: 1 + 50 = 51 queries for 50 products

// FIX: Eager load categories with Include
var productsWithCategory = await context.Products
    .Include(p => p.Category)
    .AsNoTracking()
    .ToListAsync();
foreach (var product in productsWithCategory)
{
    Console.WriteLine($"{product.Name} - {product.Category.Name}");
}
