using Microsoft.EntityFrameworkCore;

// Define the compiled query (do this once at startup)
private static readonly Func<AppDbContext, string, Task<Product?>> _getProductByName =
    EF.CompileAsyncQuery((AppDbContext ctx, string name) =>
        ctx.Products.FirstOrDefault(p => p.Name == name));

// Use the compiled query
public async Task<Product?> GetProductByNameAsync(string name)
{
    await using var context = _contextFactory.CreateDbContext();
    return await _getProductByName(context, name);
}

// Update all inactive products to inactive status in one SQL statement
await context.Products
    .Where(p => !p.IsActive && p.CreatedAt < DateTime.UtcNow.AddDays(-30))
    .ExecuteUpdateAsync(s => s.SetProperty(p => p.IsActive, false));

// Delete all archived products in one SQL statement
await context.Products
    .Where(p => p.Status == "Archived")
    .ExecuteDeleteAsync();
